    var max = top.length ? top[0].n : 1;
    var bl = Object.keys(blocked).map(function (k) { return { k: k, n: blocked[k] }; }).sort(function (a, b) { return b.n - a.n; });
    var tog = function (id, label) {
      var on = insBy === id;
      return '<button data-tg-insby="' + id + '" style="padding:3px 8px;font:700 8.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.05em;cursor:pointer;border:1px solid ' +
