    var jobs = _chunk(live, 3).map(function (batch) {
      var body = batch.map(function (u, i) {
        return "[" + (i + 1) + "] SECTION: " + u.heading + "\n" +
          "netImpact: " + (u.netImpact || "(no tracked changes in this section)") + "\n" +
