  // ── FACT RESOLUTION ──────────────────────────────────────────────────
  // Demand-driven: we only ever extract a fact that (a) the caller doesn't
  // already have and (b) a rule STILL IN PLAY needs. Narrowing by the known
  // facts first matters — a France rule scoped to NDAs creates no demand on
  // an MSA, so an MSA that needs nothing costs nothing at all.
  function requiredFacts(known) {
    var k = known || {};
    var have = {};
    Object.keys(k).forEach(function (f) { if (k[f]) have[f] = 1; });
    // Rules that survive on what we already know.
    var survivors = scanCandidates(k);
    // ...plus rules blocked ONLY by a missing fact — those are the demand.
    var wanted = {};
