      if (!r || r.status !== "active") return;
      var conds = conditionsOf(r), missing = [], blockedByValue = false;
      conds.forEach(function (c) {
        if (c.facet === "clauseId" || c.facet === "sectionKey") return;
        if (have[c.facet]) {
          // A fact we HAVE that doesn't match kills the rule outright — it
          // creates no demand for anything else.
          var want = canon(c.value), got = canon(k[c.facet]);
          var list = String(c.value || "").split(/[,;]+/).map(canon).filter(Boolean);
          var bad = (c.op === "eq" && got !== want) || (c.op === "ne" && got === want) ||
                    (c.op === "in" && list.indexOf(got) < 0 && want !== got) ||
                    (c.op === "nin" && (list.indexOf(got) >= 0 || want === got));
          if (bad) blockedByValue = true;
        } else if (isExtractable(c.facet)) {
          missing.push(c.facet);
        }
