      if (!blockedByValue) missing.forEach(function (f) { wanted[f] = (wanted[f] || 0) + 1; });
    });
    return { fields: Object.keys(wanted), demand: wanted, alreadyApplicable: survivors.length };
  }

  // Cache lives in settings (key/value) so it survives closing the taskpane
  // without needing a new IDB store.
  var FACT_CACHE_KEY = "team_guidance.facts";
  function _factCache() {
    try { return JSON.parse(eli.settings.get(FACT_CACHE_KEY) || "{}") || {}; } catch (_) { return {}; }
  }
  var FACT_CACHE_MAX = 200;
  function _factCacheWrite(all) {
    var keys = Object.keys(all);
    if (keys.length > FACT_CACHE_MAX) {
      keys.sort(function (a, b) { return String((all[b] || {}).at || "").localeCompare(String((all[a] || {}).at || "")); })
        .slice(FACT_CACHE_MAX).forEach(function (k) { delete all[k]; });
    }
    try { eli.settings.set(FACT_CACHE_KEY, JSON.stringify(all)); } catch (_) {}
  }
  function _docKey(sections) {
    var s = (sections || []).slice(0, 6).map(function (x) { return x.heading + x.text.slice(0, 200); }).join("|");
    var h = 0;
    for (var i = 0; i < s.length; i++) { h = ((h << 5) - h + s.charCodeAt(i)) | 0; }
    return "d" + (h >>> 0).toString(36) + "_" + (sections || []).length;
