    return (c && c.facts) ? c.facts : null;
  }

  // One call, only the missing fields, prompt + schema built from FIELDS.
  function extractFacts(fields, sections) {
    var want = (fields || []).filter(isExtractable);
    if (!want.length) return Promise.resolve({});
    if (!eli.ai || typeof eli.ai.completeJSON !== "function") return Promise.resolve({});
    var pre = (sections || []).slice(0, 6).map(function (s) { return s.heading + "\n" + s.text.slice(0, 1500); }).join("\n\n");
    var gl = (sections || []).filter(function (s) { return /govern|jurisdict|applicable law/i.test(s.heading); })
      .map(function (s) { return s.heading + "\n" + s.text.slice(0, 1200); }).join("\n\n");
    var prompt =
      "Read this contract and report ONLY the fields listed. Colgate-Palmolive is OUR side; the counterparty is the other party.\n\n" +
      want.map(function (id, i) { var f = fieldById(id); return (i + 1) + ". " + id + " — " + f.prompt; }).join("\n") +
      "\n\nReturn an empty string for anything the document does not actually state. Do not guess.\n\n" +
      "=== PREAMBLE / OPENING ===\n" + pre +
      (gl ? "\n\n=== GOVERNING LAW ===\n" + gl : "") +
      "\n\nReturn ONLY JSON:\n{ \"facts\": [ { \"field\": \"<id>\", \"value\": \"<value or empty>\", " +
      "\"confidence\": \"high\"|\"low\", \"evidence\": \"<the words you read it from>\" } ] }";
    return Promise.resolve(eli.ai.completeJSON(prompt)).then(function (res) {
      var out = {};
      var list = (res && (res.facts || res)) || [];
      (Array.isArray(list) ? list : []).forEach(function (x) {
        if (!x || !x.field || !String(x.value || "").trim()) return;
        out[String(x.field)] = { value: String(x.value).trim(), confidence: x.confidence || "low", evidence: x.evidence || "" };
      });
      return out;
    }).catch(function () { return {}; });
  }

  // The whole flow: what's needed → cached? → extract → cache. Returns the
  // flat facts map callers pass into evaluate().
  function resolveFacts(known, sections, opts) {
    var o = opts || {};
    var key = o.docKey || _docKey(sections);
    var cache = _factCache(), entry = cache[key] || { facts: {}, meta: {} };
    var merged = {};
    Object.keys(known || {}).forEach(function (f) { if (known[f]) merged[f] = known[f]; });
    Object.keys(entry.facts || {}).forEach(function (f) { if (!merged[f]) merged[f] = entry.facts[f]; });
    var need = requiredFacts(merged).fields.filter(function (f) { return !merged[f]; });
    if (!need.length) return Promise.resolve({ facts: merged, extracted: [], docKey: key, cached: true });
    return _fillFacts(key, need, sections).then(function (r) {
      r.names.forEach(function (f) { merged[f] = r.entry.facts[f]; });
      return { facts: merged, extracted: r.names, meta: r.entry.meta, docKey: key, cached: false };
    });
  }
  function _fillFacts(key, need, sections) {
    return extractFacts(need, sections).then(function (got) {
      var cache = _factCache(), entry = cache[key] || { facts: {}, meta: {} };
      var names = Object.keys(got);
      names.forEach(function (f) { entry.facts[f] = got[f].value; entry.meta[f] = got[f]; });
      // Remember which fields came back empty so we don't re-ask every time.
      need.forEach(function (f) { if (!entry.meta[f]) entry.meta[f] = { value: "", confidence: "none" }; });
