  // before go to the AI, once.
  function factsOf(fields, sections, opts) {
    var key = (opts && opts.docKey) || _docKey(sections);
    var want = (fields || []).filter(isExtractable);
    var have = function () {
      var e = _factCache()[key] || { facts: {} }, out = {};
      want.forEach(function (f) { if (e.facts && e.facts[f]) out[f] = e.facts[f]; });
      return { facts: out, docKey: key };
    };
