    return _fillFacts(key, need, sections).then(have);
  }

  // Public: facts + document -> which rules apply where, and which the
  // redlines actually implicate. Registered on the tool API so other tools
  // can consume it without reimplementing any of this.
  function evaluateGuidance(facts, sections) {
    var dropped = [];
    var cands = scanCandidates(facts || {}, dropped);
    var clauseNames = [], seen = {};
    cands.forEach(function (r) {
      var cid = _clauseIdOf(r);
      if (cid && !seen[cid.toLowerCase()]) { seen[cid.toLowerCase()] = 1; clauseNames.push(cid); }
    });
    return scanMapClauses(sections, clauseNames).then(function (clauseMap) {
      var byHeading = {}, units = [], unlocated = [], diag = [];
      sections.forEach(function (s) { byHeading[s.heading] = s; });
      // RR's pairing: a section is audited against ITS OWN guidance only.
      // Cross-producting every rule over every section is what produced noise.
      function attach(sec, r) {
        var u = null;
        units.forEach(function (x) { if (x.heading === sec.heading) u = x; });
        if (!u) { u = { heading: sec.heading, sec: sec, rules: [] }; units.push(u); }
        if (u.rules.indexOf(r) < 0) u.rules.push(r);
      }
      // Which rules belong to which section, and which apply everywhere.
      var docWide = [], bySection = {};
      cands.forEach(function (r) {
        var cid = _clauseIdOf(r);
        if (!cid) { docWide.push(r); diag.push({ id: r.id, clauseId: "", matched: "(document-wide)" }); return; }
        var head = clauseMap[cid] || "";
        var sec = head ? byHeading[head] : null;
        if (!sec) {                                   // fall back to token overlap
          var hits = _matchSections(cid, sections);
          if (hits.length) sec = hits[0].sec;
        }
        diag.push({ id: r.id, clauseId: cid, matched: sec ? sec.heading : "" });
        if (sec) (bySection[sec.heading] = bySection[sec.heading] || []).push(r);
        else unlocated.push({ r: r, clauseId: cid });  // reported, not forced onto sections
      });
      // ITERATE SECTIONS, not rules — RR's shape. Every redlined section is
      // examined against its own guidance PLUS the document-wide rules, so a
      // rule like "never accept uncapped liability" is judged against the
      // section where liability actually moved rather than against a merged
      // summary of the whole agreement. Repetition is handled at REPORT time,
      // not by narrowing what gets evaluated.
      var redlined = sections.filter(function (s) { return s.redlined; });
      (redlined.length ? redlined : sections.slice(0, 10)).forEach(function (sec) {
        var mine = (bySection[sec.heading] || []).concat(docWide);
        if (!mine.length) return;                     // RR's skipReason
