      });
      // A mapped clause that wasn't redlined still deserves a look.
      Object.keys(bySection).forEach(function (h) {
        var already = units.some(function (u) { return u.heading === h; });
        if (!already && byHeading[h]) units.push({ heading: h, sec: byHeading[h], rules: bySection[h] });
      });
      return scanNetImpacts(sections).then(function (impacts) {
        units.forEach(function (u) {
          u.netImpact = impacts[u.heading] || "";
