    return '<div data-tg-scrim style="position:fixed;inset:0;background:rgba(15,23,42,.45);z-index:100000;"></div>' +
      '<div style="position:fixed;top:0;right:0;bottom:0;width:min(600px,96%);background:#fff;z-index:100001;display:flex;flex-direction:column;box-shadow:-16px 0 40px rgba(15,23,42,.3);font-family:Inter,sans-serif;">' +
