        (insOpen ? insightsHtml() : '') +
        (nLocal ? '<div style="background:#fff7ed;border-bottom:1px solid #fdba74;padding:9px 26px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;flex-shrink:0;">' +
          '<span style="font:600 11.5px/1.5 Inter,sans-serif;color:#9a3412;flex:1;min-width:200px;"><b>' + nLocal + ' of your rule' + (nLocal === 1 ? " is" : "s are") + ' only on this computer.</b> The team won\'t see ' + (nLocal === 1 ? "it" : "them") + ' until ' + (nLocal === 1 ? "it is" : "they are") + ' published.</span>' +
          '<button data-tg-publish style="padding:7px 14px;font:800 10px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.05em;cursor:pointer;background:linear-gradient(135deg,#0f766e,#0d5c56);color:#fff;border:1px solid #0d5c56;">Publish now</button></div>' : '') +
        '<div style="flex:1;overflow-y:auto;padding:16px 26px 40px;">' +
          (view === "pend"
            ? (vis.length
                ? '<div style="background:linear-gradient(180deg,#fffbeb,#fef3c7);border:1px solid #fbbf24;border-left:4px solid #d97706;padding:11px 15px;margin-bottom:16px;font:500 11.5px/1.5 Inter,sans-serif;color:#78350f;">' +
                    '<b>Objections raised in Review Redlines land here.</b> Promoting makes a rule live for everyone on the next run. Dismissing archives it.</div>' +
                  vis.map(pendCard).join("")
                : '<div style="padding:40px;text-align:center;font:500 12.5px Inter,sans-serif;color:#94a3b8;">Nothing pending. Disagreements raised in Review Redlines appear here for promotion.</div>')
            : (vis.length
                ? (nPend ? '<div style="background:linear-gradient(180deg,#fffbeb,#fef3c7);border:1px solid #fbbf24;border-left:4px solid #d97706;padding:11px 15px;margin-bottom:16px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;">' +
                    '<span style="font:800 11px Inter,sans-serif;color:#92400e;text-transform:uppercase;letter-spacing:.06em;">⚑ ' + nPend + ' pending</span>' +
                    '<span style="font:500 11.5px Inter,sans-serif;color:#78350f;flex:1;min-width:200px;">Reviewers disagreed with ELI. Review and promote into rules.</span>' +
                    '<button data-tg-view="pend" style="padding:8px 14px;font:800 10px Inter,sans-serif;text-transform:uppercase;cursor:pointer;background:linear-gradient(135deg,#d97706,#b45309);color:#fff;border:1px solid #92400e;">Review →</button></div>' : '') +
                  // Collapsible groups. State is keyed by groupBy too, so
                  // switching the grouping doesn't inherit odd collapse.
                  '<div style="display:flex;gap:7px;margin-bottom:10px;">' +
                    '<button data-tg-fold="all" style="padding:4px 10px;font:700 9.5px Inter,sans-serif;text-transform:uppercase;cursor:pointer;background:#fff;color:#64748b;border:1px solid #cbd5e1;">Collapse all</button>' +
                    '<button data-tg-fold="none" style="padding:4px 10px;font:700 9.5px Inter,sans-serif;text-transform:uppercase;cursor:pointer;background:#fff;color:#64748b;border:1px solid #cbd5e1;">Expand all</button>' +
                  '</div>' +
                  keys.map(function (k) {
                    var ck = groupBy + "::" + k;
                    var shut = !!collapsed[ck];
                    return '<div style="margin-bottom:' + (shut ? "8px" : "22px") + ';">' +
                      '<div data-tg-group-toggle="' + esc(ck) + '" style="display:flex;align-items:center;gap:9px;margin-bottom:9px;padding-bottom:6px;border-bottom:1px solid #cbd5e1;cursor:pointer;user-select:none;">' +
                        '<span style="font:700 10px/1 Inter,sans-serif;color:#94a3b8;width:9px;">' + (shut ? "▸" : "▾") + '</span>' +
                        '<span style="font:800 11px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:.11em;color:#334155;">' + esc(k) + '</span>' +
                        '<span style="font:700 9.5px/1 Inter,sans-serif;color:#64748b;background:#e2e8f0;padding:3px 7px;">' + groups[k].length + '</span>' +
                      '</div>' + (shut ? "" : groups[k].map(ruleCard).join("")) + '</div>';
                  }).join("")
                : '<div style="padding:40px;text-align:center;font:500 12.5px Inter,sans-serif;color:#94a3b8;">' +
                    (q || srcFilter !== "all" ? 'Nothing matches that filter.' : 'No guidance yet. Click <b>+ New guidance</b> to write your first rule.') + '</div>')) +
        '</div>' +
      '</div>' + editorHtml() + scanPanelHtml();
  }

  // Team rows + flattened playbook guidance in one list. Playbook rows are
  // virtual (never persisted) and re-derived on every refresh.
  // Pull teammates' guidance before reading. Without this the tool only ever
  // showed what Review Redlines happened to have synced — so an objection
  // raised by a colleague was invisible here until RR was opened.
  // _tcPullRemote self-throttles to once / 90s, so this is cheap to call.
  function pullRemote() {
    if (typeof window._tcPullRemote !== "function") return Promise.resolve();
    return Promise.resolve(window._tcPullRemote()).catch(function () {});
  }
  function refresh(opts) {
    var pre = (opts && opts.skipPull) ? Promise.resolve() : pullRemote();
    return pre.then(function () {
      return Promise.all([loadAll(), loadPlaybookRows()]);
    }).then(function (res) {
      rows = res[0].concat(res[1]);
      render();
    });
  }

  // ── Actions ──────────────────────────────────────────────────────────
  function newDraft() {
    var id = identity();
    draft = {
      isNew: true, conds: [],
      row: { id: genId(), text: "", rationale: "", reference: "", tier: "default",
             authorName: id.name, authorEmail: id.email, authorGroup: id.group },
    };
    render();
  }
  function editDraft(rid) {
    var r = rows.filter(function (x) { return x.id === rid; })[0];
    if (!r) return;
    draft = { isNew: false, row: JSON.parse(JSON.stringify(r)), conds: conditionsOf(r).slice() };
    render();
  }
  function readDraftFields(root) {
    if (!draft) return;
    var t = root.querySelector("[data-tg-text]"), ra = root.querySelector("[data-tg-rat]"), rf = root.querySelector("[data-tg-ref]");
    var tg = root.querySelector("[data-tg-trig]"), ac = root.querySelector("[data-tg-action]");
    if (t) draft.row.text = t.value;
    if (ra) draft.row.rationale = ra.value;
    if (rf) draft.row.reference = rf.value;
    if (tg) draft.row.trigger = tg.value;
    if (ac) draft.row.action = ac.value;
    draft.conds.forEach(function (c, i) {
      var f = root.querySelector('[data-tg-cf="' + i + '"]'), o = root.querySelector('[data-tg-co="' + i + '"]'), v = root.querySelector('[data-tg-cv="' + i + '"]');
      if (f && f.value !== c.facet) { c.facet = f.value; c.value = ""; c._other = false; }  // new facet, new vocabulary
      if (o) c.op = o.value;
      if (v) {
        if (v.value === "__other__") { c._other = true; c.value = ""; }
        else c.value = v.value;
      }
    });
  }
  function saveDraft() {
    if (!draft) return Promise.resolve();
    var r = draft.row;
    if (!String(r.text || "").trim()) {
      if (typeof showToast === "function") showToast("Guidance text is required.", "warn");
      return Promise.resolve();
    }
    var conds = draft.conds.filter(function (c) { return c.facet && String(c.value || "").trim(); })
      .map(function (c) {
        rememberValue(c.facet, c.value);       // grow the vocabulary from real use
        return { facet: c.facet, op: c.op, value: String(c.value).trim() };
      });
    var out = buildRow(r, conds, draft.isNew ? "active" : (r.status === "pending" ? "pending" : (r.status || "active")));
    return put(out).then(publish).then(function (pushRes) {
      draft = null;
      try { eli.log.event("tool", "team_guidance_saved", { isNew: !!out.createdAt, tier: out.tier, conds: conds.length }); } catch (_) {}
      toastPush(pushRes, "Guidance saved");
      return refresh({ skipPull: true });
    });
  }
  function buildRow(r, conds, status) {
    var now = new Date().toISOString();
    var sc = scopeFromConditions(conds);
    return {
      id: r.id,
      // sectionId kept for backward compat with the RR pane + older clients.
      sectionId: canon(sc.agreementType || "") + "::" + canon("") + "::" + canon(""),
      scopeVersion: 1,
      scope: sc,
      conditions: conds,
      agreementType: sc.agreementType || "",
      articleLabel: r.articleLabel || "",
      sectionLabel: r.sectionLabel || "",
      authorName: r.authorName, authorEmail: r.authorEmail, authorGroup: r.authorGroup,
      createdAt: r.createdAt || now,
      updatedAt: now,
      text: String(r.text).trim(),
      rationale: String(r.rationale || "").trim(),
      reference: String(r.reference || "").trim(),
      trigger: String(r.trigger || "").trim(),
      action: String(r.action || "").trim(),
      tier: r.tier || "default",
      origin: r.origin || "authored",
      evidence: r.evidence || [],
      tags: r.tags || [],
      status: status,
      syncState: "local",
    };
  }
  // Another tool's rule (Turn the Draft's "Save as guidance"): live at once
  // and published like one written here. { ok, id, published, why }.
  function addRule(e) {
    if (!e || !String(e.text || "").trim()) return Promise.resolve({ ok: false, why: "no text" });
    var id = identity();
    var conds = (e.conditions || []).filter(function (c) { return c && c.facet && String(c.value || "").trim(); })
      .map(function (c) { return { facet: c.facet, op: c.op || "eq", value: String(c.value).trim() }; });
    var row = buildRow({ id: genId(), text: e.text, rationale: e.rationale, sectionLabel: e.sectionLabel, tier: e.tier,
      origin: "derived", tags: e.tags, authorName: id.name, authorEmail: id.email, authorGroup: id.group }, conds, "active");
    return put(row).then(publish).then(function (res) {
      refresh({ skipPull: true });
      var ok = !!(res && res.ok !== false);
      return { ok: true, id: row.id, published: ok, why: ok ? "" : pushWhy(res) };
    });
  }
  // Taking one back (its Undo): archived, the way the library removes a rule.
  function removeRule(rid) {
    return Promise.resolve(eli.storage.get(STORE, rid)).then(function (r) {
      if (!r) return { ok: false };
      r.status = "archived"; r.updatedAt = new Date().toISOString(); r.syncState = "local";
      return put(r).then(publish).then(function () { refresh({ skipPull: true }); return { ok: true }; });
    });
  }
  function archive(rid) {
    var r = rows.filter(function (x) { return x.id === rid; })[0];
    if (!r || r._virtual) return Promise.resolve();
    r.status = "archived"; r.updatedAt = new Date().toISOString(); r.syncState = "local";
    return put(r).then(publish).then(function () { return refresh({ skipPull: true }); });
  }
  function promote(rid) {
    var r = rows.filter(function (x) { return x.id === rid; })[0];
    if (!r) return Promise.resolve();
    r.status = "active";
    r.promotedBy = identity().name;
    r.promotedAt = new Date().toISOString();
    r.updatedAt = r.promotedAt;
    r.syncState = "local";
    r.tags = (Array.isArray(r.tags) ? r.tags : []).filter(function (t) { return t !== "pending"; }).concat(["promoted"]);
    return put(r).then(publish).then(function (pushRes) {
      toastPush(pushRes, "Promoted");
      return refresh({ skipPull: true });
    });
  }

  function _open() {
    if (overlay) overlay.remove();
    overlay = document.createElement("div");
    overlay.id = "eliTeamGuidanceOverlay";
    overlay.style.cssText = "position:fixed;inset:0;z-index:99998;";
    overlay.addEventListener("click", function (ev) {
      var t = ev.target;
      if (!t || !t.closest) return;
      var g = function (a) { var el = t.closest("[" + a + "]"); return el ? el.getAttribute(a) : null; };
      if (t.closest("[data-tg-close]")) { overlay.remove(); overlay = null; return; }
      if (t.closest("[data-tg-scrim]") || t.closest("[data-tg-cancel]")) {
        draft = null; if (scan) scan.open = false; render(); return;
      }
      if (t.closest("[data-tg-scan]")) {
        scan = scan || { facts: {}, sections: [] };
        scan.open = true;
        if (!scan.facts.agreementType && window._eliDocType) scan.facts.agreementType = window._eliDocType;
        render(); return;
      }
      if (t.closest("[data-tg-runscan]") && scan) { runScan(); return; }
      var v = g("data-tg-view"); if (v) { view = v; render(); return; }
      var gb = g("data-tg-group"); if (gb) { groupBy = gb; render(); return; }
      var sf = g("data-tg-src"); if (sf) { srcFilter = sf; render(); return; }
      var gt = g("data-tg-group-toggle");
      if (gt) { collapsed[gt] = !collapsed[gt]; render(); return; }
      var fold = g("data-tg-fold");
      if (fold) {
        if (fold === "none") collapsed = {};
        else visible().forEach(function (r) { collapsed[groupBy + "::" + groupKey(r)] = true; });
        render(); return;
      }
      if (t.closest("[data-tg-ins]")) { insOpen = !insOpen; render(); return; }
      var ib = g("data-tg-insby"); if (ib) { insBy = ib; render(); return; }
      if (t.closest("[data-tg-new]")) { newDraft(); return; }
      if (t.closest("[data-tg-publish]")) { publishNow(); return; }
      var ed = g("data-tg-edit"); if (ed) { editDraft(ed); return; }
      var ar = g("data-tg-archive"); if (ar) { archive(ar); return; }
      var pr = g("data-tg-promote"); if (pr) { promote(pr); return; }
      var tr = g("data-tg-tier"); if (tr && draft) { readDraftFields(overlay); draft.row.tier = tr; render(); return; }
      if (t.closest("[data-tg-cadd]") && draft) { readDraftFields(overlay); draft.conds.push({ facet: "agreementType", op: "eq", value: "" }); render(); return; }
      var cd = g("data-tg-cdel"); if (cd != null && draft) { readDraftFields(overlay); draft.conds.splice(Number(cd), 1); render(); return; }
      var cp = g("data-tg-cpick"); if (cp != null && draft) { readDraftFields(overlay); draft.conds[Number(cp)]._other = false; render(); return; }
      var cvd = g("data-tg-cvdel");
      if (cvd != null && draft) {                 // remove one chip
        var parts = String(cvd).split(":"), cRow = draft.conds[Number(parts[0])];
        if (cRow) {
          var vals = _splitVals(cRow.value);
          vals.splice(Number(parts[1]), 1);
          cRow.value = vals.join(", ");
        }
        render(); return;
      }
      if (t.closest("[data-tg-save]") && draft) { readDraftFields(overlay); saveDraft(); return; }
    });
    overlay.addEventListener("change", function (ev) {
      var el = ev.target;
      if (!el || !el.getAttribute) return;
      var fct = el.getAttribute("data-tg-fact");   // scan facts: no draft required
      if (fct && scan) {
        scan.facts[fct] = el.value;
        // Refresh only the counter — a full repaint would rebuild the
        // dropdowns and steal focus mid-selection.
        var lc = overlay.querySelector("[data-tg-livecount]");
        if (lc) lc.innerHTML = liveCountHtml();
        return;
      }
      if (!draft) return;
      var addSel = el.getAttribute("data-tg-cvadd");
      if (addSel != null) {                       // multi-select: append a value
        var ci = Number(addSel), cc = draft.conds[ci];
        if (cc && el.value) {
          if (el.value === "__other__") { cc._other = true; }
          else {
            var have = _splitVals(cc.value);
            if (have.indexOf(el.value) < 0) have.push(el.value);
            cc.value = have.join(", ");
            rememberValue(cc.facet, el.value);
          }
          render();
        }
        return;
      }
      if (el.getAttribute("data-tg-cv") != null || el.getAttribute("data-tg-cf") != null ||
          el.getAttribute("data-tg-co") != null) {
        readDraftFields(overlay);
        render();
      }
    });
    overlay.addEventListener("keydown", function (ev) {
      var el = ev.target;
      if (ev.key !== "Enter" || !el || !el.getAttribute || !draft) return;
      var ai = el.getAttribute("data-tg-cvadd");
      if (ai == null || el.tagName !== "INPUT") return;
      ev.preventDefault();
      var cc = draft.conds[Number(ai)], val = String(el.value || "").trim();
      if (cc && val) {
        var have = _splitVals(cc.value);
        if (have.indexOf(val) < 0) have.push(val);
        cc.value = have.join(", ");
        rememberValue(cc.facet, val);
        cc._other = false;
        render();
      }
    });
    overlay.addEventListener("input", function (ev) {
      var el = ev.target;
      if (!el || !el.getAttribute) return;
      if (el.getAttribute("data-tg-q") != null) {
        q = el.value;
        // Repaint only the list so the search box keeps focus.
        var host = overlay.querySelectorAll("div");
        render();
        var box = overlay.querySelector("[data-tg-q]");
        if (box) { box.focus(); box.setSelectionRange(box.value.length, box.value.length); }
      }
    });
    document.body.appendChild(overlay);
    Promise.all([loadAgreementTypes(), loadPlaybookClauses()]).then(refresh);
  }

  eli.register({
    tile: { app_team_guidance: _open },
    guidance: {
      open: _open,
      getAll: loadAll,
      // Rows a prompt may use: active only, pending excluded.
      // facts + sections -> which rules apply where and which the redlines
      // implicate. Same engine the Scan panel uses.
      evaluate: function (facts, sections) { return evaluateGuidance(facts || {}, sections || []); },
      // Demand-driven fact resolution. requiredFacts costs nothing (no AI);
      // resolveFacts extracts ONLY what a still-applicable rule needs, and
      // caches per document so it happens once per matter.
      fields: function () { return FIELDS.slice(); },
      requiredFacts: function (known) { return requiredFacts(known || {}); },
      resolveFacts: function (known, sections, opts) { return resolveFacts(known || {}, sections || [], opts); },
      factsFor: function (docKey) { return factsFor(docKey); },
      // Let another tool that has already read the document (Agreement at a
      // Glance) hand its findings over, so the same facts aren't extracted
      // twice. Only registry fields are accepted.
      seedFacts: function (facts, sections, opts) {
        var key = (opts && opts.docKey) || _docKey(sections || []);
        var cache = _factCache(), entry = cache[key] || { facts: {}, meta: {} };
        var took = [];
        Object.keys(facts || {}).forEach(function (f) {
          var v = String(facts[f] == null ? "" : facts[f]).trim();
          if (!v || !fieldById(f) || fieldById(f).supplied) return;
          if (/^not specified$/i.test(v)) return;
          entry.facts[f] = v;
          entry.meta[f] = { value: v, confidence: "seeded", source: (opts && opts.source) || "glance" };
          took.push(f);
        });
        if (!took.length) return { docKey: key, seeded: [] };
        entry.at = new Date().toISOString();
        cache[key] = entry;
        _factCacheWrite(cache);
        return { docKey: key, seeded: took };
      },
      readDocument: function () { return scanReadDoc(); },
      facts: function (fields, sections, opts) { return factsOf(fields, sections, opts); },
      // A document's facts with where each came from (AI and its confidence, a tool's seed, the user) — ELI Agent's
      // setup screen shows them ([TD-FACTS]). docKey from facts() / seedFacts(), or the sections.
      factsMeta: function (docKey, sections) {
        var e = _factCache()[docKey || _docKey(sections || [])];
        return e ? { facts: e.facts || {}, meta: e.meta || {} } : { facts: {}, meta: {} };
      },
      add: function (entry) { return addRule(entry); },
      remove: function (id) { return removeRule(id); },
      forPrompt: function () {
        return loadAll().then(function (all) {
          return all.filter(function (r) { return r && r.status !== "archived" && r.status !== "pending"; });
        });
      },
    },
  });
  eli.log.event("tool", "team_guidance_init", {});
}
